#!/usr/bin/env node
// Digest a captured conversation JSONL into friction signals. Reads JSONL on stdin.
import { createInterface } from 'node:readline';

const trunc = (s, n) => { s = String(s ?? '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };
const rows = [];
const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
for await (const line of rl) { if (!line.trim()) continue; try { rows.push(JSON.parse(line)); } catch {} }

const ts = r => r.timestamp ? Date.parse(r.timestamp) : null;
const entries = rows.filter(r => ts(r));
const t0 = entries.length ? ts(entries[0]) : 0, t1 = entries.length ? ts(entries[entries.length - 1]) : 0;

const humanTurns = [];
const errors = [];
const toolCalls = [];
let assistantTexts = 0, lastAssistant = '';
const gaps = [];

for (let i = 0; i < entries.length; i++) {
  const r = entries[i], c = r.message?.content;
  if (i > 0) { const g = ts(r) - ts(entries[i - 1]); if (g > 20000) gaps.push({ g: Math.round(g / 1000), after: describe(entries[i - 1]), at: r.timestamp }); }
  if (r.type === 'user' && Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text') humanTurns.push({ t: r.timestamp, text: trunc(b.text, 900) });
      if (b.type === 'tool_result' && b.is_error) errors.push(trunc(typeof b.content === 'string' ? b.content : JSON.stringify(b.content), 260));
    }
  } else if (r.type === 'user' && typeof c === 'string') humanTurns.push({ t: r.timestamp, text: trunc(c, 900) });
  else if (r.type === 'assistant' && Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text') { assistantTexts++; lastAssistant = trunc(b.text, 700); }
      if (b.type === 'tool_use') toolCalls.push({ name: b.name, arg: trunc(b.input?.command ?? b.input?.file_path ?? b.input?.pattern ?? b.input?.prompt ?? JSON.stringify(b.input ?? {}), 170), t: r.timestamp });
    }
  }
}
function describe(r) {
  const c = r.message?.content;
  if (Array.isArray(c)) { const tu = c.find(b => b.type === 'tool_use'); if (tu) return `${tu.name}: ${trunc(tu.input?.command ?? tu.input?.file_path ?? JSON.stringify(tu.input ?? {}), 110)}`; }
  return r.type;
}
const counts = {};
for (const t of toolCalls) counts[t.name] = (counts[t.name] || 0) + 1;

console.log(`## duration ${((t1 - t0) / 60000).toFixed(1)} min | entries ${entries.length} | tool calls ${toolCalls.length} | assistant texts ${assistantTexts}`);
console.log(`## tools: ${Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}=${v}`).join(' ')}`);
console.log(`\n### HUMAN/PROMPT TURNS (${humanTurns.length})`);
for (const h of humanTurns) console.log(`- [${h.t}] ${h.text}`);
console.log(`\n### ERRORS (${errors.length}, unique)`);
const seen = new Set();
for (const e of errors) { const k = e.slice(0, 90); if (seen.has(k)) continue; seen.add(k); console.log(`- ${e}`); }
console.log(`\n### GAPS >20s (${gaps.length})`);
for (const g of gaps.sort((a, b) => b.g - a.g).slice(0, 14)) console.log(`- ${g.g}s after ${g.after}`);
console.log(`\n### BASH COMMANDS`);
for (const t of toolCalls.filter(t => t.name === 'Bash')) console.log(`- ${t.arg}`);
console.log(`\n### FINAL ASSISTANT TEXT\n${lastAssistant}`);

